import { HttpProblem, internalError } from "./problems.mjs";
import { encodeSegment } from "./ids.mjs";

// Request parsing and response building for the HTTP API payload v2 event
// shape. Every response carries the service-description link the spec
// requires on all responses, so a client can discover the server from any
// URL it holds.

const TEXT_TYPES = /^(text\/|application\/(json|xml|javascript|problem\+json|linkset\+json|jose\+json|jwk\+json))|\+(json|xml)(;|$)/i;

export function isTextContentType(contentType) {
  return TEXT_TYPES.test((contentType ?? "").trim());
}

// API Gateway hands rawPath percent-DECODED (sam local does not always), so
// each segment is decoded defensively: a segment that fails to decode is kept
// as sent.
function decodeSegment(segment) {
  try {
    return decodeURIComponent(segment);
  } catch {
    return segment;
  }
}

export function parseRequest(event) {
  const headers = Object.fromEntries(
    Object.entries(event.headers ?? {}).map(([name, value]) => [name.toLowerCase(), value])
  );
  const method = (event.requestContext?.http?.method ?? event.httpMethod ?? "GET").toUpperCase();
  const rawPath = event.rawPath ?? event.path ?? "/";
  const proto = headers["x-forwarded-proto"] ?? "https";
  const host = headers.host ?? event.requestContext?.domainName ?? "localhost";
  const base = `${proto}://${host}`;
  const rawQueryString = event.rawQueryString ?? "";
  const query = Object.fromEntries(new URLSearchParams(rawQueryString));

  const body = event.body == null || event.body === ""
    ? null
    : event.isBase64Encoded
      ? Buffer.from(event.body, "base64")
      : Buffer.from(event.body, "utf8");

  // Segments as ids (decoded); the path re-encoded from them is what a client
  // signed when its ids carry characters outside the unreserved set.
  const segments = rawPath === "/" ? [] : rawPath.split("/").slice(1).map(decodeSegment);
  const trailingSlash = rawPath.length > 1 && rawPath.endsWith("/");
  const ids = trailingSlash ? segments.slice(0, -1) : segments;
  const encodedPath = "/" + ids.map(encodeSegment).join("/") + (trailingSlash ? "/" : "");
  const search = rawQueryString ? `?${rawQueryString}` : "";

  // What the gateway authorizer established (strings only).
  const auth = event.requestContext?.authorizer?.lambda ?? {};

  return {
    method,
    headers,
    body,
    base,
    host,
    rawPath,
    ids,
    trailingSlash,
    query,
    pathParameters: event.pathParameters ?? {},
    auth,
    // The URL as the gateway delivered it, and the URL the client signed.
    url: `${base}${rawPath}${search}`,
    encodedUrl: `${base}${encodedPath}${search}`,
    contentType: headers["content-type"],
    isHead: method === "HEAD",
  };
}

export const serviceLink = (base) => `<${base}/>; rel="service"`;

// Builds the payload v2 response. `body` may be an object (serialized as
// JSON), a string, or a Buffer (base64-encoded unless its content type is
// textual). A 204/304 never carries a body or a Content-Type.
export function respond(req, { status = 200, headers = {}, body, contentType } = {}) {
  const outHeaders = {
    Link: serviceLink(req.base),
    ...headers,
  };
  if (status === 204 || status === 304 || body === undefined) {
    return { statusCode: status, headers: outHeaders, body: "" };
  }
  let payload;
  let isBase64Encoded = false;
  if (Buffer.isBuffer(body)) {
    const type = contentType ?? "application/octet-stream";
    outHeaders["Content-Type"] = type;
    if (isTextContentType(type)) {
      payload = body.toString("utf8");
    } else {
      payload = body.toString("base64");
      isBase64Encoded = true;
    }
  } else if (typeof body === "string") {
    outHeaders["Content-Type"] = contentType ?? "text/plain; charset=utf-8";
    payload = body;
  } else {
    outHeaders["Content-Type"] = contentType ?? "application/json";
    payload = JSON.stringify(body);
  }
  if (req.isHead) {
    payload = "";
    isBase64Encoded = false;
  }
  return { statusCode: status, headers: outHeaders, body: payload, isBase64Encoded };
}

export const json = (req, status, body, headers = {}) => respond(req, { status, headers, body });

export const noContent = (req, headers = {}) => respond(req, { status: 204, headers });

// A write response must not be cached (the spec's Cache-Control: no-store on
// non-idempotent operations).
export const NO_STORE = { "Cache-Control": "no-store" };

export function problemResponse(req, err) {
  const problem = err instanceof HttpProblem ? err : internalError();
  if (!(err instanceof HttpProblem)) {
    console.error("Unhandled error:", err);
  }
  return respond(req, {
    status: problem.status,
    headers: { ...NO_STORE, ...(problem.headers ?? {}) },
    body: problem.toJSON(),
    contentType: "application/problem+json",
  });
}

// 308 to the canonical trailing-slash form of a container URL.
export function redirect(req, location) {
  return respond(req, { status: 308, headers: { Location: location } });
}

// Reads the JSON body of a request, or throws the given problem.
export function parseJsonBody(req, { required = true, problem }) {
  if (req.body === null) {
    if (required) {
      throw problem("The request body is empty.");
    }
    return {};
  }
  let parsed;
  try {
    parsed = JSON.parse(req.body.toString("utf8"));
  } catch {
    throw problem("The request body is not valid JSON.");
  }
  if (typeof parsed !== "object" || parsed === null || Array.isArray(parsed)) {
    throw problem("The request body must be a JSON object.");
  }
  return parsed;
}

// The If-Match / If-None-Match preconditions of a write, as S3 takes them.
export function preconditions(req) {
  const ifMatch = req.headers["if-match"];
  const ifNoneMatch = req.headers["if-none-match"];
  return {
    ...(ifMatch !== undefined && { ifMatch }),
    ...(ifNoneMatch !== undefined && { ifNoneMatch }),
  };
}
